    if (cb) {
      // getter with cb
      getter = () => {
        try {
          return source()
        } catch (err) {
          handleError(err, instance, ErrorCodes.WATCH_GETTER)
        }
      }
    } else {
      // no cb -> simple effect
      getter = () => {
        if (cleanup) {
          cleanup()
        }
