    if (immediate) {
      job(true)
    } else {
      oldValue = effect.run()
    }
  } else if (flush === 'post') {
    const suspense = instance && instance.suspense
    if (suspense && suspense.pendingBranch) {
      suspense.effects.push(effect.run.bind(effect))
    } else {
      queuePostFlushCb(effect.run.bind(effect))
    }
