  // subscribers are notified in reverse order so that batched effects can
  // be invoked in their original order at the end of the batch. However,
  // effects that opt out of batching (e.g. sync watchers) are triggered
  // immediately, so collect them here and invoke them in original order.
  let syncSubs: Link[] | undefined
  for (let link = this.subs; link; link = link.prevSub) {
    if (link.sub.flags & EffectFlags.NO_BATCH) {
      ;(syncSubs || (syncSubs = [])).push(link)
    } else {
      link.sub.notify()
    }
  }
  if (syncSubs) {
    for (let i = syncSubs.length - 1; i >= 0; i--) {
      syncSubs[i].sub.notify()
    }
  }
} finally {
  endBatch()
}

