import { describe, expect, it } from 'vitest'
import { computed, ref } from '@vue/reactivity'
import { watch } from '@vue/runtime-core'

describe('sync watcher order', () => {
  it('ref', () => {
    const n = ref(0)
    const order: number[] = []
    for (let i = 0; i < 5; i++) watch(n, () => order.push(i), { flush: 'sync' })
    n.value++
    expect(order).toEqual([0, 1, 2, 3, 4])
  })
  it('computed', () => {
    const n = ref(0)
    const c = computed(() => n.value)
    const order: number[] = []
    for (let i = 0; i < 5; i++) watch(c, () => order.push(i), { flush: 'sync' })
    n.value++
    expect(order).toEqual([0, 1, 2, 3, 4])
  })
  it('mixed', () => {
    const n = ref(0)
    const c = computed(() => n.value)
    const order: string[] = []
    watch(n, () => order.push('a'), { flush: 'sync' })
    watch(c, () => order.push('b'), { flush: 'sync' })
    watch(n, () => order.push('c'), { flush: 'sync' })
    n.value++
    expect(order).toEqual(['a', 'b', 'c'])
  })
})
EOF
